begin;
do $test$ declare u uuid:=gen_random_uuid();payload jsonb;a jsonb;b jsonb;w credit_balances%rowtype; jid uuid; stamp timestamptz; obj text; url text; evidence jsonb; bucket text;begin
 insert into auth.users(id,email) values(u,'legacy-create-'||u||'@example.invalid');
 insert into profiles(id,email) values(u,'legacy-create-'||u||'@example.invalid') on conflict(id) do nothing;
 insert into credit_balances(user_id,balance,reserved,topup_credits) values(u,150,0,150) on conflict(user_id) do update set balance=150,reserved=0,topup_credits=150,rolled_over_credits=0,current_subscription_credits=0,bonus_credits=0;
 payload:=jsonb_build_object('user_id',u,'production_type','image','package_id','image-basic','title','Fixture','prompt','Fixture image','status','queued','generation_status','automation_queued','request_metadata',jsonb_build_object('requestFingerprint','fixture A'),'input_json','{}'::jsonb,'materials_json','[]'::jsonb,'estimated_credits',100,'reserved_credits',100,'output_json','{}'::jsonb,'legal_acceptance_snapshot',jsonb_build_object('accepted',true));
 a:=studio_legacy_create(u,payload);if a->>'state'<>'created' then raise exception 'create failed %',a;end if;
 b:=studio_legacy_create(u,payload);if b->>'state'<>'existing' or b#>>'{production,id}'<>a#>>'{production,id}' then raise exception 'duplicate failed';end if;
 b:=studio_legacy_create(u,jsonb_set(payload,'{estimated_credits}','101'));if b->>'code' is distinct from 'idempotency_terms_mismatch' then raise exception 'changed price accepted';end if;
 b:=studio_legacy_create(u,jsonb_set(payload,'{reserved_credits}','99'));if b->>'code' is distinct from 'idempotency_terms_mismatch' then raise exception 'changed initial reservation accepted';end if;
 b:=studio_legacy_create(u,jsonb_set(payload,'{package_id}','"image-other"'));if b->>'code' is distinct from 'idempotency_terms_mismatch' then raise exception 'changed package accepted';end if;
 b:=studio_legacy_create(u,jsonb_set(payload,'{request_metadata,requestFingerprint}','"fixture B"'));if b->>'state'<>'insufficient' then raise exception 'double reserve';end if;
 b:=studio_wallet_spend(u,51,'fixture-key-0001','fixture');if b->>'state'<>'insufficient' then raise exception 'hold consumed';end if;
 b:=studio_wallet_spend(u,20,'fixture-key-0001','fixture');if b->>'state'<>'spent' then raise exception 'spend failed';end if;
 b:=studio_wallet_spend(u,20,'fixture-key-0001','fixture');if b->>'state'<>'already_spent' then raise exception 'same terms not idempotent';end if;
 b:=studio_wallet_spend(u,10,'fixture-key-0001','fixture');if b->>'code'<>'idempotency_terms_mismatch' then raise exception 'different terms accepted';end if;
 b:=studio_wallet_spend(u,20,'fixture-key-0001','other');if b->>'code'<>'idempotency_terms_mismatch' then raise exception 'different action accepted';end if;
 select * into w from credit_balances where user_id=u;if w.balance<>130 or w.reserved<>100 or w.topup_credits<>130 then raise exception 'wallet mismatch';end if;
 if (select count(*) from credit_events where user_id=u and type='reserve')<>1 or (select count(*) from credit_events where user_id=u and type='spend')<>1 then raise exception 'event count';end if;
 b:=studio_legacy_refund_reviewed((a#>>'{production,id}')::uuid);if b->>'state' is distinct from 'reconcile_required' then raise exception 'active job refunded';end if;
 update production_requests set status='failed',output_json=jsonb_build_object('creditResolution',jsonb_build_object('status','admin_review_required')) where id=(a#>>'{production,id}')::uuid;
 b:=studio_legacy_refund_reviewed((a#>>'{production,id}')::uuid);if b->>'state' is distinct from 'refunded' or (b->>'refunded_credits')::int<>100 then raise exception 'reviewed refund failed';end if;
 b:=studio_legacy_refund_reviewed((a#>>'{production,id}')::uuid);if b->>'state' is distinct from 'already_refunded' or (b->>'refunded_credits')::int<>0 then raise exception 'duplicate refund';end if;
 select * into w from credit_balances where user_id=u;if w.balance<>130 or w.reserved<>0 or w.topup_credits<>130 then raise exception 'refund minted credits or changed buckets';end if;
 if (select count(*) from credit_events where user_id=u and type='refund')<>1 then raise exception 'duplicate refund event';end if;
 if has_function_privilege('anon','public.studio_legacy_refund_reviewed(uuid)','EXECUTE') or has_function_privilege('authenticated','public.studio_legacy_refund_reviewed(uuid)','EXECUTE') or not has_function_privilege('service_role','public.studio_legacy_refund_reviewed(uuid)','EXECUTE') then raise exception 'refund permission mismatch';end if;
 payload:=jsonb_set(jsonb_set(jsonb_set(payload,'{request_metadata,requestFingerprint}','"fixture expiry"'),'{reserved_credits}','50'),'{estimated_credits}','50');
 a:=studio_legacy_create(u,payload);if a->>'state' is distinct from 'created' then raise exception 'expiry fixture creation failed';end if;
 b:=studio_legacy_expire_unstarted((a#>>'{production,id}')::uuid);if b->>'state' is distinct from 'reconcile_required' then raise exception 'early expiry accepted';end if;
 update production_requests set created_at=now()-interval '25 hours',started_at=now(),automation_status='queued' where id=(a#>>'{production,id}')::uuid;
 b:=studio_legacy_expire_unstarted((a#>>'{production,id}')::uuid);if b->>'state' is distinct from 'reconcile_required' then raise exception 'started job expired';end if;
 update production_requests set started_at=null where id=(a#>>'{production,id}')::uuid;
 b:=studio_legacy_expire_unstarted((a#>>'{production,id}')::uuid);if b->>'state' is distinct from 'expired' or (b->>'released_credits')::int<>50 then raise exception 'expiry failed';end if;
 b:=studio_legacy_expire_unstarted((a#>>'{production,id}')::uuid);if b->>'state' is distinct from 'already_expired' or (b->>'released_credits')::int<>0 then raise exception 'duplicate expiry';end if;
 select * into w from credit_balances where user_id=u;if w.balance<>130 or w.reserved<>0 or w.topup_credits<>130 then raise exception 'expiry minted credits';end if;
 if (select count(*) from credit_events where user_id=u and type='refund' and note='legacy-expire:'||(a#>>'{production,id}'))<>1 then raise exception 'duplicate expiry event';end if;
 if has_function_privilege('anon','public.studio_legacy_expire_unstarted(uuid)','EXECUTE') or has_function_privilege('authenticated','public.studio_legacy_expire_unstarted(uuid)','EXECUTE') or not has_function_privilege('service_role','public.studio_legacy_expire_unstarted(uuid)','EXECUTE') then raise exception 'expiry permission mismatch';end if;
 payload:=jsonb_set(jsonb_set(jsonb_set(payload,'{request_metadata,requestFingerprint}','"fixture other hold"'),'{reserved_credits}','40'),'{estimated_credits}','40');
 b:=studio_legacy_create(u,payload);if b->>'state' is distinct from 'created' then raise exception 'other hold fixture';end if;
 payload:=jsonb_set(jsonb_set(jsonb_set(payload,'{request_metadata,requestFingerprint}','"fixture cancel"'),'{reserved_credits}','51'),'{estimated_credits}','51');
 a:=studio_legacy_create(u,payload);if a->>'state' is distinct from 'created' then raise exception 'cancel fixture';end if;
 b:=studio_legacy_cancel_unstarted(gen_random_uuid(),(a#>>'{production,id}')::uuid);if b->>'state' is distinct from 'not_found' then raise exception 'cross owner cancellation';end if;
 update production_requests set started_at=now() where id=(a#>>'{production,id}')::uuid;
 b:=studio_legacy_cancel_unstarted(u,(a#>>'{production,id}')::uuid);if b->>'state' is distinct from 'reconcile_required' then raise exception 'started job cancelled';end if;
 update production_requests set started_at=null where id=(a#>>'{production,id}')::uuid;
 b:=studio_legacy_cancel_unstarted(u,(a#>>'{production,id}')::uuid);if b->>'state' is distinct from 'cancelled' or (b->>'cancellation_fee')::int<>26 or (b->>'refund_amount')::int<>25 then raise exception 'cancel settlement mismatch';end if;
 b:=studio_legacy_cancel_unstarted(u,(a#>>'{production,id}')::uuid);if b->>'state' is distinct from 'already_cancelled' then raise exception 'cancel replay';end if;
 select * into w from credit_balances where user_id=u;if w.balance<>104 or w.reserved<>40 or w.topup_credits<>104 then raise exception 'cancel wallet or other hold mismatch';end if;
 if (select count(*) from credit_events where user_id=u and note in ('legacy-cancel-spend:'||(a#>>'{production,id}'),'legacy-cancel-release:'||(a#>>'{production,id}')))<>2 then raise exception 'cancel event count';end if;
 if has_function_privilege('anon','public.studio_legacy_cancel_unstarted(uuid,uuid)','EXECUTE') or has_function_privilege('authenticated','public.studio_legacy_cancel_unstarted(uuid,uuid)','EXECUTE') or not has_function_privilege('service_role','public.studio_legacy_cancel_unstarted(uuid,uuid)','EXECUTE') then raise exception 'cancel permission mismatch';end if;
 payload:=jsonb_set(jsonb_set(jsonb_set(payload,'{request_metadata,requestFingerprint}','"fixture uncertainty"'),'{reserved_credits}','20'),'{estimated_credits}','20');
 a:=studio_legacy_create(u,payload);if a->>'state' is distinct from 'created' then raise exception 'failure review fixture';end if;
 b:=studio_legacy_hold_failed_start(gen_random_uuid(),(a#>>'{production,id}')::uuid,'image_pipeline',false);if b->>'state' is distinct from 'not_found' then raise exception 'cross owner review';end if;
 b:=studio_legacy_hold_failed_start(u,(a#>>'{production,id}')::uuid,'image_pipeline',true);if b->>'state' is distinct from 'provider_poll_required' then raise exception 'known provider overwritten';end if;
 b:=studio_legacy_hold_failed_start(u,(a#>>'{production,id}')::uuid,'image_pipeline',false);if b->>'state' is distinct from 'review_required' then raise exception 'failure review missing';end if;
 b:=studio_legacy_hold_failed_start(u,(a#>>'{production,id}')::uuid,'image_pipeline',false);if b->>'state' is distinct from 'already_in_review' then raise exception 'failure review duplicate';end if;
 b:=studio_legacy_refund_reviewed((a#>>'{production,id}')::uuid);if b->>'state' is distinct from 'reconcile_required' then raise exception 'ambiguous outcome refunded';end if;
 select * into w from credit_balances where user_id=u;if w.balance<>104 or w.reserved<>60 or w.topup_credits<>104 then raise exception 'failure changed wallet';end if;
 if has_function_privilege('anon','public.studio_legacy_hold_failed_start(uuid,uuid,text,boolean)','EXECUTE') or has_function_privilege('authenticated','public.studio_legacy_hold_failed_start(uuid,uuid,text,boolean)','EXECUTE') then raise exception 'failure review permission mismatch';end if;
 payload:=jsonb_set(jsonb_set(jsonb_set(payload,'{request_metadata,requestFingerprint}','"fixture settlement"'),'{reserved_credits}','30'),'{estimated_credits}','30');
 a:=studio_legacy_create(u,payload);if a->>'state' is distinct from 'created' then raise exception 'settlement fixture';end if;
 jid:=(a#>>'{production,id}')::uuid;select updated_at into stamp from production_requests where id=jid;
 bucket:='fixture-'||u::text;obj:=jid::text||'/final-render.mp4';url:='https://example.invalid/storage/v1/object/public/'||bucket||'/'||obj;
 evidence:=jsonb_build_object('readyGate',jsonb_build_object('passed',true,'missing','[]'::jsonb),'qualityGate',jsonb_build_object('status','passed'),'finalAssetMirror',jsonb_build_object('status','mirrored_provider_url_primary','storedUrl',url),'finalVideoUrl',url,'providerStatus','shotstack_succeeded');
 b:=studio_legacy_settle_video(u,jid,stamp,bucket,obj,url,evidence);if b->>'state' is distinct from 'artifact_missing' then raise exception 'missing artifact accepted %',b;end if;
 insert into storage.buckets(id,name,public) values(bucket,bucket,true);
 insert into storage.objects(bucket_id,name,metadata) values(bucket,obj,jsonb_build_object('mimetype','video/mp4','size',12345));
 b:=studio_legacy_settle_video(u,jid,stamp,bucket,obj,url,jsonb_set(evidence,'{readyGate,passed}','false'));if b->>'state' is distinct from 'quality_unverified' then raise exception 'bad quality accepted';end if;
 b:=studio_legacy_settle_video(u,jid,stamp-interval '1 second',bucket,obj,url,evidence);if b->>'state' is distinct from 'reconcile_required' then raise exception 'stale snapshot accepted';end if;
 b:=studio_legacy_settle_video(gen_random_uuid(),jid,stamp,bucket,obj,url,evidence);if b->>'state' is distinct from 'not_found' then raise exception 'cross owner accepted';end if;
 b:=studio_legacy_settle_video(u,jid,stamp,bucket,obj,url,evidence);if b->>'state' is distinct from 'settled' or (b->>'charged')::int<>30 then raise exception 'settle failed %',b;end if;
 b:=studio_legacy_settle_video(u,jid,stamp,bucket,obj,url,evidence);if b->>'state' is distinct from 'already_settled' or (b->>'charged')::int<>0 then raise exception 'double charge';end if;
 select * into w from credit_balances where user_id=u;if w.balance<>74 or w.reserved<>60 or w.topup_credits<>74 then raise exception 'wallet mismatch';end if;
 if (select count(*) from credit_events where user_id=u and note='legacy-video-spend:'||jid::text)<>1 then raise exception 'duplicate spend';end if;
end $test$;select 'PASS: atomic legacy reserve+create, duplicate reuse, hold protected, conflicting idempotency rejected, reviewed refund once, balance unchanged, service-only permissions, expiry once, started and premature expiry blocked, cancellation once, odd fee rounding, other holds and ownership protected, ambiguous failure holds preserved, no retry or automatic refund, atomic video settlement fixture passed' result;rollback;